.826737+00","updated_at":"2026-10-20 22:40:22.826737+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-2:SC02-S198","pod_slug":"talk-bollocks-2","scene_number":2,"scene_label":"Chapter 2","scene_title":"Language Learning Can Bridge Gaps","scene_subtitle":null,"difficulty":null,"sentence_number":198,"global_order":323,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:22.826737+00","updated_at":"2026-10-20 22:40:22.826737+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-2:SC02-S199","pod_slug":"talk-bollocks-2","scene_number":2,"scene_label":"Chapter 2","scene_title":"Language Learning Can Bridge Gaps","scene_subtitle":null,"difficulty":null,"sentence_number":199,"global_order":324,"speaker":"ARAN","english_text":"But if you come up with a group then that is a longterm thing and I think, yeah, that's really important.","author_notes":null,"created_at":"2026-10-20 22:40:22.826737+00","updated_at":"2026-10-20 22:40:22.826737+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-2:SC02-S20","pod_slug":"talk-bollocks-2","scene_number":2,"scene_label":"Chapter 2","scene_title":"Language Learning Can Bridge Gaps","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":145,"speaker":"ARAN","english_text":"By doing one day per year.","author_notes":null,"created_at":"2026-10-20 22:40:22.698693+00","updated_at":"2026-10-20 22:40:22.698693+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-2:SC02-S200","pod_slug":"talk-bollocks-2","scene_number":2,"scene_label":"Chapter 2","scene_title":"Language Learning Can Bridge Gaps","scene_subtitle":null,"difficulty":null,"sentence_number":200,"global_order":325,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"